    END IF;
  END LOOP;
  FOREACH r IN ARRAY ARRAY['tll_customer_runtime','tll_cart_runtime','tll_broker_runtime','tll_provisional_runtime','tll_bridge_runtime'] LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN RAISE EXCEPTION 'Runtime role is absent: %',r; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM pg_auth_members e JOIN pg_roles granted ON granted.oid=e.roleid JOIN pg_roles member ON member.oid=e.member
    WHERE member.rolname IN ('tll_customer_runtime','tll_cart_runtime','tll_broker_runtime','tll_provisional_runtime','tll_bridge_runtime')
      AND NOT ((granted.rolname,member.rolname) IN (('tll_customer_executor','tll_customer_runtime'),('tll_cart_gateway','tll_cart_runtime'),
        ('tll_broker_executor','tll_broker_runtime'),('tll_provisional_executor','tll_provisional_runtime'),('tll_bridge_executor','tll_bridge_runtime')))) THEN
