    WHERE (granted.rolname,member.rolname) IN (('tll_customer_executor','tll_customer_runtime'),('tll_cart_gateway','tll_cart_runtime'),
      ('tll_broker_executor','tll_broker_runtime'),('tll_provisional_executor','tll_provisional_runtime'),('tll_bridge_executor','tll_bridge_runtime'))
