  END IF;
  IF has_table_privilege(operator_name,(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='tll_customer_private' AND c.relname='control'),'UPDATE')
    OR has_table_privilege(operator_name,(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='tll_broker_private' AND c.relname='control'),'UPDATE')
    OR has_table_privilege(operator_name,(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='tll_provisional_private' AND c.relname='control'),'UPDATE')
    OR has_table_privilege(operator_name,(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='tll_bridge_private' AND c.relname='control'),'UPDATE') THEN
